static void test_dbl(void) {
    TEST_SUITE("p256_point_dbl");
    for (int i = 0; i < NDBL; i++) {
        uint8_t in[96], out[96];
        jac_frombytes(in, &DBL_IN[i]);
        p256_point_dbl(out, in);
        ASSERT_EQ("dbl(P) matches reference", 1, jac_tobytes_eq(out, &DBL_OUT[i]));
    }

    // in-place: out aliasing in must give the same result.
    uint8_t buf[96];
    jac_frombytes(buf, &DBL_IN[0]);
    p256_point_dbl(buf, buf);
    ASSERT_EQ("dbl(P) in place matches reference", 1, jac_tobytes_eq(buf, &DBL_OUT[0]));
}

int main(void) {
    test_dbl();
    test_summary();
    return 0;
}
